// The web's screen rules as data (resources/web/content.json, generated by scripts/gen_i18n.mjs from
// curriculum.ts, campaign.ts, campaignReport.ts, debrief.ts, shortcuts.ts and academy.ts): curriculum
// stages, campaign constants, default shortcuts and the Academy lessons. Never retyped, so a web
// change reaches the desktop through the generator (check_i18n.mjs fails on drift).
#pragma once

#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

namespace tradelab::desktop {

struct Stage {
  std::string id;
  std::vector<std::string> requires_;  // direct prerequisites
  std::vector<std::string> missions;   // assessment missions
  std::vector<std::string> lessons;    // Academy lessons (stages without a mission)
  std::vector<std::string> unlocks;    // "short", "leverage", "optionsBuy", "optionsWrite"
};

struct LessonCandle {
  double o = 0, h = 0, l = 0, c = 0, v = 0;
};

struct LessonChart {
  std::string market;
  std::string interval;
  std::vector<LessonCandle> candles;
  int highlight = 0;  // 1-based bar to highlight, 0 = none
  int known = 0;      // bars already closed (0 = all); the rest is the unknown future
  bool anatomy = false;
};

struct LessonChoice {
  enum class Kind : std::uint8_t { Bar, Pct, Text };
  Kind kind = Kind::Bar;
  int bar = 0;
  double value = 0;  // percent (1.21 = +1,21%)
  std::string id;    // text choice id
};

struct LessonStep {
  std::string id;
  std::string phase;  // concept, demo, decision, transfer
  std::optional<LessonChart> chart;
  std::vector<LessonChoice> choices;  // empty: not a question
  int answer = -1;
  [[nodiscard]] bool question() const { return !choices.empty(); }
};

struct AcademyLesson {
  std::string id;
  std::string stage;
  std::vector<LessonStep> steps;
};

struct WebContent {
  std::vector<Stage> stages;
  int locked_leverage_cap = 2;
  std::string campaign_capital;
  std::string campaign_min_capital;
  int campaign_history = 20;
  int report_min_trades = 30;
  int after_release_bars = 10;
  std::vector<std::string> shortcut_actions;
  std::vector<std::pair<std::string, std::string>> default_keymap;  // action -> key, in action order
  std::vector<AcademyLesson> lessons;

  [[nodiscard]] const Stage* stage(std::string_view id) const;
  [[nodiscard]] const AcademyLesson* lesson(std::string_view id) const;
};

// Parses content.json; std::nullopt when it is not a valid document.
std::optional<WebContent> parse_web_content(std::string_view json);
// The content built into the binary, parsed once.
const WebContent& web_content();

}  // namespace tradelab::desktop
